<?php
/* v38 - Botonera de cabina agrupada para presentacion de OF. */
session_start();
require_once 'conexion.php';
require_once 'auth.php';
require_once 'sistema_comercial.php';
require_once 'material_hueco_of.php';
require_once 'orden_fabricacion_tipos.php';
require_once 'orden_fabricacion_layout.php';
asegurarSistemaUsuarios($conexion); asegurarSistemaComercial($conexion); exigirRoles(array('ADMINISTRADOR','TECNICO','COMERCIAL'));
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function cantVista($v){$n=(float)$v;return abs($n-round($n))<.000001?number_format($n,0,',','.'):number_format($n,2,',','.');}
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); if(!$id) die('Orden inválida.');
$st=$conexion->prepare("SELECT p.*,c.cotizacion_numero,COALESCE(p.referencia,c.referencia) AS referencia,cl.clientes_codigo,cl.clientes_nomfantasia,COALESCE(u.usuario_nombre,p.usuario,'') AS responsable_comercial FROM pedidos p LEFT JOIN cotizaciones c ON c.cotizacion_id=p.cotizacion_id JOIN clientes cl ON cl.clientes_id=p.cliente_id LEFT JOIN usuarios u ON u.usuario_id=p.usuario_id WHERE p.pedido_id=?");
$st->bind_param('i',$id);$st->execute();$p=$st->get_result()->fetch_assoc();$st->close();if(!$p)die('Pedido inexistente.');
$st=$conexion->prepare("SELECT modulo,concepto,codigo,descripcion,cantidad,formula_aplicada FROM pedidos_detalle WHERE pedido_id=? ORDER BY orden_visual,pedido_detalle_id");$st->bind_param('i',$id);$st->execute();$r=$st->get_result();$todos=array();while($x=$r->fetch_assoc())$todos[]=$x;$st->close();
$tipo=oftTipoSolicitado($p,$todos,(string)($_GET['tipo']??'')); if($tipo==='')die('El pedido no tiene órdenes de fabricación disponibles.');
$datosFormulario=json_decode((string)($p['datos_formulario']??''),true);if(!is_array($datosFormulario))$datosFormulario=array();
$detalles=oftFiltrarDetalles($todos,$tipo);
if($tipo==='SENALIZACION_ACCESORIOS'){
    $detalles=expandirBotonerasFabricacion($detalles,$datosFormulario);
    $tieneAppind=false;
    foreach($detalles as $d){if(strtoupper(trim((string)($d['codigo']??'')))==='APPIND'){$tieneAppind=true;break;}}
    if($tieneAppind){
        $detalles=ofExpandirAppindComoMaterialHueco($detalles);
    }else{
        $mhAut=ofMaterialHuecoIndicadorAutonomo($conexion,$datosFormulario);
        if($mhAut){foreach($mhAut as $mh)$detalles[]=$mh;}
    }
}
$sufijo=oftSufijoUrl($tipo);
$materialHuecoOf=$tipo==='CONTROL'?calcularMaterialHuecoOrden($conexion,$datosFormulario):array('materiales'=>array(),'advertencias'=>array(),'titulo'=>'');
$esControl=$tipo==='CONTROL';$esSenal=$tipo==='SENALIZACION_ACCESORIOS';$esSuministros=$tipo==='SUMINISTROS';
$titulo=$esControl?'Orden de fabricación de Control':($esSenal?'Orden de fabricación de Señalización, Accesorios y Repuestos':'Orden de preparación de suministros');
$eyebrow=$esControl?'Producción · Control técnico':($esSenal?'Producción · Pulsadores · Señalización · Accesorios · Repuestos':'Preparación · Control · Despacho');
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($titulo)?> <?=e(numeroDocumentoVisible($p['pedido_numero']))?></title><style>
:root{--ink:#183446;--navy:#183446;--green:#138754;--amber:#b56a00;--blue:#2675d8;--bg:#f2f6f8;--line:#dce6eb;--muted:#6f818d}
body{font-family:Arial,sans-serif;background:var(--bg);margin:0;color:var(--ink)}.wrap{max-width:1260px;margin:0 auto;padding:24px}.tools{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}.btn{display:inline-flex;align-items:center;justify-content:center;padding:10px 14px;background:#edf2f4;color:#334c5b;text-decoration:none;border-radius:9px;font-weight:900;font-size:11px}.btn.pdf{background:#183446;color:#fff}.btn.mod{background:#ffeaed;color:#b92334}.sheet{background:#fff;border:1px solid var(--line);border-radius:18px;box-shadow:0 16px 42px rgba(20,45,62,.075);overflow:hidden}.doc-head{position:relative;padding:25px 28px;background:#193344;color:#fff;border-left:7px solid <?=$esControl?'#138754':($esSenal?'#c17400':'#2875d5')?>}.doc-head .eyebrow{font-size:10px;font-weight:900;letter-spacing:.14em;text-transform:uppercase;color:#b9cad5}.doc-head h1{margin:6px 0 4px;font-size:28px;letter-spacing:-.035em}.doc-head p{margin:0;color:#ced9df;font-weight:700}.meta{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px;padding:19px 24px;background:#f7fafb;border-bottom:1px solid #e1e8ec}.meta-item{padding:12px 13px;background:#fff;border:1px solid #dde7eb;border-radius:11px;min-height:48px}.meta-item span{display:block;margin-bottom:5px;color:#748692;font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.05em}.meta-item strong{font-size:13px}.content{padding:24px 25px 30px}.section-title{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:4px 0 13px;padding:11px 13px;border-radius:10px;background:<?=$esControl?'#eaf6ef':($esSenal?'#fff4e4':'#edf4fd')?>;color:<?=$esControl?'#0d6d42':($esSenal?'#8a5200':'#195fae')?>;border-left:4px solid <?=$esControl?'#138754':($esSenal?'#c17400':'#2875d5')?>}.section-title h2{margin:0;font-size:15px}.section-title small{font-weight:800;opacity:.8}.nota{color:#627581;margin:-4px 0 14px;font-size:12px}.table-wrap{overflow:auto;border:1px solid #dbe5ea;border-radius:12px}table{width:100%;border-collapse:separate;border-spacing:0}th,td{padding:12px 13px;border-bottom:1px solid #e5ecef;text-align:left;vertical-align:middle}th{background:#203746;color:#fff;font-size:10px;text-transform:uppercase;letter-spacing:.055em}tbody tr:last-child td{border-bottom:0}tbody tr:nth-child(even){background:#fafcfd}.num{width:36px;text-align:center;color:#758792;font-weight:900}.qty{font-size:15px;font-weight:900}.code{font-family:Consolas,monospace;font-weight:700}.check{width:20px;height:20px;border:2px solid #9aabb5;border-radius:5px;display:inline-block;background:#fff}.checks{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.check-card{display:flex;align-items:center;gap:10px;padding:12px 13px;border:1px solid #dbe5ea;border-radius:10px;background:#fbfcfd}.signatures{display:grid;grid-template-columns:repeat(2,1fr);gap:24px;margin-top:28px}.signature{padding-top:10px;border-top:1px solid #83949f;color:#596d79;font-size:11px;font-weight:700}.aviso{margin:14px 0;padding:11px 13px;background:#fff9e8;border:1px solid #f0dca7;border-radius:10px;color:#735b13;font-size:12px}.grupo{margin-top:22px}
