</style></head><body><?php require __DIR__.'/menu.php'; ?><main class="wrap"><div class="tools"><a class="btn" href="ordenes_fabricacion.php">← VOLVER</a><a class="btn pdf" href="generar_pdf_orden_fabricacion.php?id=<?=(int)$id?>&tipo=<?=e($sufijo)?>" target="_blank">VER PDF</a><?php if(esRol('ADMINISTRADOR')):?><a class="btn mod" href="index.php?editar_pedido=<?=(int)$id?>">MODIFICAR PEDIDO</a><?php endif;?></div><article class="sheet"><header class="doc-head"><div class="eyebrow"><?=e($eyebrow)?></div><h1><?=e($titulo)?></h1><p>Pedido <?=e(numeroDocumentoVisible($p['pedido_numero']))?> · Revisión <?=(int)($p['revision']??0)?></p></header><section class="meta"><div class="meta-item"><span>Cliente</span><strong><?=e($p['clientes_codigo'].' — '.$p['clientes_nomfantasia'])?></strong></div><div class="meta-item"><span>Referencia / obra</span><strong><?=e($p['referencia']?:'—')?></strong></div><div class="meta-item"><span>Origen</span><strong><?=e($p['cotizacion_numero']?numeroDocumentoVisible($p['cotizacion_numero']):'Pedido directo')?></strong></div><div class="meta-item"><span>Responsable comercial</span><strong><?=e($p['responsable_comercial']?:'—')?></strong></div><div class="meta-item"><span>Estado</span><strong><?=e($p['estado'])?></strong></div><div class="meta-item"><span>OF disponible</span><strong><?=e(oftEtiquetaTipo($tipo))?></strong></div></section><section class="content">
<?php if($esSuministros):?>
<div class="section-title"><h2>Materiales a preparar</h2><small>Pedido de suministros</small></div><div class="table-wrap"><table><thead><tr><th>#</th><th>Cantidad</th><th>Código</th><th>Descripción</th><th>Preparado</th><th>Controlado</th></tr></thead><tbody><?php $n=0;foreach($detalles as $x):$n++;?><tr><td class="num"><?=$n?></td><td class="qty"><?=cantVista($x['cantidad'])?></td><td class="code"><?=e($x['codigo']?:'—')?></td><td><?=e($x['descripcion']?:$x['concepto'])?></td><td><span class="check"></span></td><td><span class="check"></span></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($esSenal):?>
<div class="section-title"><h2>Pulsadores, Señalización, Accesorios y Repuestos</h2><small>Mismo número de pedido</small></div><p class="nota">Esta OF reúne los renglones de Señalización, Accesorios y Repuestos del pedido. Los Límites c/soporte se mantienen en Material de Hueco de la OF de Control y no se duplican aquí.</p>
<?php foreach(array('SENALIZACION'=>'SEÑALIZACIÓN / BOTONERAS','ACCESORIOS'=>'ACCESORIOS','REPUESTOS'=>'REPUESTOS') as $mod=>$label):$grupo=array_values(array_filter($detalles,function($d)use($mod){return oftModuloDetalle($d)===$mod;}));if(!$grupo)continue;?><div class="grupo"><div class="section-title"><h2><?=e($label)?></h2><small><?=count($grupo)?> renglón(es)</small></div><div class="table-wrap"><table><thead><tr><th>Concepto</th><th>Código</th><th>Descripción técnica</th><th>Cantidad</th><th>Verificado</th></tr></thead><tbody><?php foreach($grupo as $x):?><tr><td><?=e($x['concepto'])?></td><td class="code"><?=e($x['codigo']?:'—')?></td><td><?=e($x['descripcion']?:$x['concepto'])?></td><td class="qty"><?=cantVista($x['cantidad'])?></td><td><span class="check"></span></td></tr><?php endforeach;?></tbody></table></div></div><?php endforeach;?>
<?php else:?>
<div class="section-title"><h2>Detalle técnico de producción</h2><small>Control / Obra</small></div><div class="table-wrap"><table><thead><tr><th>Concepto</th><th>Código</th><th>Descripción técnica</th><th>Cantidad</th><th>Observación / fórmula</th></tr></thead><tbody><?php foreach($detalles as $x):?><tr><td><?=e($x['concepto'])?></td><td class="code"><?=e($x['codigo'])?></td><td><?=e($x['descripcion'])?></td><td class="qty"><?=cantVista($x['cantidad'])?></td><td><?=e($x['formula_aplicada'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!empty($materialHuecoOf['materiales'])||!empty($materialHuecoOf['advertencias'])):?><div class="section-title" style="margin-top:22px"><h2>Material de hueco</h2><small><?=e($materialHuecoOf['titulo'])?></small></div><div class="table-wrap"><table><thead><tr><th>Cantidad</th><th>Descripción</th><th>Unidad</th><th>Fórmula</th></tr></thead><tbody><?php foreach($materialHuecoOf['materiales'] as $mh):?><tr><td class="qty"><?=e(mhOfFormatearCantidad((float)$mh['cantidad']))?></td><td><?=e($mh['nombre'])?></td><td><?=e($mh['unidad'])?></td><td><?=e($mh['formula'])?></td></tr><?php endforeach;?><?php foreach($materialHuecoOf['advertencias'] as $aviso):?><tr><td colspan="4"><strong>Advertencia:</strong> <?=e($aviso)?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
<?php endif;?></section></article></main></body></html>
